const fs = require('fs')
const { chromium } = require('playwright')
const { PNG } = require('pngjs')

const json = (body) => ({ status: 200, contentType: 'application/json', body: JSON.stringify(body) })
const REF = 'test-results/public-portal-references'

;(async () => {
  const { default: pixelmatch } = await import('pixelmatch')
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  await page.route('**/api/v3.0/**', (r) => r.fulfill(json({ code: 200, rows: [], data: {}, total: 0 })))
  await page.route('**/api/v2.0/**', (r) => r.fulfill(json({ code: 200, rows: [], data: [], total: 0 })))
  await page.route('**/portal/public/externalInfo/publicNotice/page*', (r) => r.fulfill(json({ code: 200, rows: [], total: 0 })))
  await page.route('**/system/platformConfig/getInfo*', (r) => r.fulfill(json({ code: 200, data: { projectId: 'e2e-public-portal', region: '姹熻嫃鐪佽嫃宸炲競', buttonDefaultColor: '' } })))

  for (const [kind, index] of [['company', 19], ['house', 20], ['permit', 23]]) {
    await page.goto(`http://127.0.0.1:8082/#/UnifiedLogin?portal=${kind}-detail`, { waitUntil: 'domcontentloaded' })
    await page.locator('.portal-detail-dialog').waitFor()
    await page.evaluate(() => document.fonts.ready)
    await page.waitForTimeout(200)
    const raw = await page.locator('.portal-detail-dialog').screenshot({ animations: 'disabled', scale: 'css' })
    fs.writeFileSync(`.claude-tmp/sim-${kind}-actual.png`, raw)
    const actual = PNG.sync.read(raw)
    const reference = PNG.sync.read(fs.readFileSync(`${REF}/ref-${index}.png`))
    const width = Math.min(actual.width, reference.width)
    const height = Math.min(actual.height, reference.height)
    const crop = (png) => {
      const target = new PNG({ width, height })
      PNG.bitblt(png, target, 0, 0, width, height, 0, 0)
      return target
    }
    const diff = new PNG({ width, height })
    const count = pixelmatch(crop(reference).data, crop(actual).data, diff.data, width, height, { threshold: 0.1, includeAA: false })
    fs.writeFileSync(`.claude-tmp/sim-${kind}-diff.png`, PNG.sync.write(diff))
    console.log(`${kind}: ref ${reference.width}x${reference.height} actual ${actual.width}x${actual.height} -> ${(100 * (1 - count / (width * height))).toFixed(3)}% (DPR1 approximation)`)
  }
  await browser.close()
})().catch((error) => { console.error(error); process.exit(1) })

