const fs = require('fs')
const path = require('path')
const { spawnSync } = require('child_process')
const { chromium } = require('playwright')
const { PNG } = require('pngjs')

const json = (body) => ({ status: 200, contentType: 'application/json', body: JSON.stringify(body) })
const REF = 'test-results/public-portal-references'
const PY = process.env.PYTHON || 'python'

/** 涓?scripts/portal-visual-downsample.py 涓€鑷达細2x 璁惧鎴浘鐢?Lanczos 缂╁埌 CSS 灏哄 */
function downsample(rawBuffer) {
  const rawPath = path.resolve('.claude-tmp/raw-2x.png')
  const cssPath = path.resolve('.claude-tmp/raw-css.png')
  fs.writeFileSync(rawPath, rawBuffer)
  const code = [
    'from PIL import Image',
    `im = Image.open(r"${rawPath}")`,
    'w, h = im.size',
    `im.resize((w // 2, h // 2), Image.Resampling.LANCZOS).save(r"${cssPath}")`
  ].join('\n')
  const result = spawnSync(PY, ['-c', code], { stdio: ['ignore', 'pipe', 'pipe'] })
  if (result.status !== 0) throw new Error(result.stderr?.toString() || `python exited ${result.status}`)
  return fs.readFileSync(cssPath)
}

