import React, { useEffect, useMemo, useState } from 'react';
import { MarketHeader } from './components/MarketHeader';
import { DistrictBanner } from './components/DistrictBanner';
import { KpiCards } from './components/KpiCards';
import { TradePanel } from './components/TradePanel';
import { AgencyPanel } from './components/AgencyPanel';
import { AreaStructurePanel } from './components/AreaStructurePanel';
import { CumulativePanel } from './components/CumulativePanel';
import { UnsoldPanel } from './components/UnsoldPanel';
import { BuyerOverviewPanel } from './components/BuyerOverviewPanel';
import { ScreenAdapter, AdaptMode } from './components/ScreenAdapter';
import {
  THEMES,
  ThemeId,
  computeAreaBrackets,
  computeDashboardKpi,
} from './data/marketData';

export function App() {
  const [selectedMonth, setSelectedMonth] = useState<string>('2026-10');
  const [selectedDistrict, setSelectedDistrict] = useState<string>('all');
  const [themeId] = useState<ThemeId>('classic-blue');
  const [isFullscreen, setIsFullscreen] = useState<boolean>(false);
  const adaptMode: AdaptMode = 'contain';

  useEffect(() => {
    const onFsChange = () => {
      setIsFullscreen(Boolean(document.fullscreenElement));
    };
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const currentTheme = THEMES[themeId];

  const kpiData = useMemo(
    () => computeDashboardKpi(selectedMonth, selectedDistrict),
    [selectedMonth, selectedDistrict],
  );

  const areaData = useMemo(
    () => computeAreaBrackets(selectedDistrict),
    [selectedDistrict],
  );

  const handleToggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen?.().catch(() => {});
    } else {
      document.exitFullscreen?.().catch(() => {});
    }
  };

  const handleResetOverview = () => {
    setSelectedMonth('2026-10');
    setSelectedDistrict('all');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div
      className={`min-h-screen ${currentTheme.pageBg} text-slate-800 flex flex-col transition-colors duration-300`}
    >
      <ScreenAdapter adaptMode={adaptMode} className={currentTheme.pageBg}>
        <div className={`w-full h-full ${currentTheme.pageBg} text-slate-800 flex flex-col overflow-hidden`}>
          <MarketHeader
            selectedMonth={selectedMonth}
            selectedDistrict={selectedDistrict}
            currentTheme={currentTheme}
            isFullscreen={isFullscreen}
            onMonthChange={setSelectedMonth}
            onDistrictChange={setSelectedDistrict}
            onToggleFullscreen={handleToggleFullscreen}
            onResetOverview={handleResetOverview}
          />

          <main className="w-full max-w-[1920px] mx-auto px-3.5 sm:px-4 py-2 flex flex-col gap-2.5 flex-1 min-h-0 overflow-hidden print-hide">
            {/* Contextual District Intelligence Banner */}
            <DistrictBanner
              selectedDistrict={selectedDistrict}
              theme={currentTheme}
              onResetDistrict={() => setSelectedDistrict('all')}
            />

            {/* Top 6-Card KPI Strip */}
            <KpiCards
              data={kpiData}
              selectedMonth={selectedMonth}
              selectedDistrict={selectedDistrict}
              theme={currentTheme}
            />

            {/* Row 1: Trade Comparison (8 cols) + Agency & Area Structure (4 cols) */}
