const OUT = 'C:/Users/Administrator/AppData/Local/Temp/mm-align'
fs.mkdirSync(OUT, { recursive: true })

async function shoot(browser, url, name, opts = {}) {
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.evaluate(() => document.fonts.ready).catch(() => {})
  await page.waitForTimeout(opts.wait || 2500)
  const file = path.join(OUT, name + '.png')
  await page.screenshot({ path: file, animations: 'disabled' })
  const info = await page.evaluate(() => {
    const el = document.querySelector('.mm-dashboard')
    const body = document.body
    return {
      title: document.title,
      dash: !!el,
      dashRect: el ? { w: Math.round(el.getBoundingClientRect().width), h: Math.round(el.getBoundingClientRect().height) } : null,
      scrollH: document.documentElement.scrollHeight,
      bodyBg: getComputedStyle(body).backgroundColor,
      textSample: (document.body.innerText || '').slice(0, 300)
    }
  }).catch(e => ({ evalError: String(e) }))
  console.log(name, JSON.stringify({ errors: errors.slice(0, 8), info }))
  await page.close()
  return file
}

async function similarity(refFile, actFile, label) {
  const { default: pixelmatch } = await import('D:/repository/门户/node_modules/pixelmatch/index.js')
  const ref = PNG.sync.read(fs.readFileSync(refFile))
  const act = PNG.sync.read(fs.readFileSync(actFile))
  const w = Math.min(ref.width, act.width), h = Math.min(ref.height, act.height)
  const crop = (png) => { const t = new PNG({ width: w, height: h }); PNG.bitblt(png, t, 0, 0, w, h, 0, 0); return t }
  const diff = new PNG({ width: w, height: h })
  const count = pixelmatch(crop(ref).data, crop(act).data, diff.data, w, h, { threshold: 0.1, includeAA: false })
  fs.writeFileSync(path.join(OUT, label + '-diff.png'), PNG.sync.write(diff))
  console.log(`SIMILARITY ${label}: ${(100 * (1 - count / (w * h))).toFixed(3)}%  (${w}x${h})`)
}

