const fs = require('fs')
const path = require('path')
const ROOT = 'C:/Users/Administrator/Downloads/苏州市房地产市场数据分析平台'
const dist = path.join(ROOT, 'dist')
const js = fs.readdirSync(path.join(dist, 'assets')).find(f => f.endsWith('.js'))
const css = fs.readdirSync(path.join(dist, 'assets')).find(f => f.endsWith('.css'))
const jsText = fs.readFileSync(path.join(dist, 'assets', js), 'utf8')
const cssText = fs.readFileSync(path.join(dist, 'assets', css), 'utf8')
console.log('js len', jsText.length, 'css len', cssText.length)
console.log('JS HEAD:', jsText.slice(0, 240))
console.log('JS TAIL:', jsText.slice(-240))
const imports = (jsText.match(/\bimport\s*[{("']/g) || []).length
const dynImports = (jsText.match(/\bimport\s*\(/g) || []).length
const exports = (jsText.match(/\bexport\s*[{]/g) || []).length
console.log({ imports, dynImports, exports, hasImportMeta: jsText.includes('import.meta'), hasSourceMappingURL: jsText.includes('sourceMappingURL') })
console.log('CSS url() refs:', (cssText.match(/url\([^)]*\)/g) || []).slice(0, 10))
console.log('CSS @import:', (cssText.match(/@import[^;]*;/g) || []).slice(0, 5))

/**
 * 由「最新版本」React 源码的 Vite 构建产物，生成无依赖单文件大屏 HTML。
 *
 * 用法：
 *   node scripts/build-market-monitor-standalone.mjs [参考项目dist目录] [输出目录]
 *
 * 参考项目（最新版源码）: C:/Users/Administrator/Downloads/苏州市房地产市场数据分析平台
 * 需先在其中执行: npx vite build --base=./
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const repoRoot = path.resolve(__dirname, '..')
const refDist = path.resolve(process.argv[2] || 'C:/Users/Administrator/Downloads/苏州市房地产市场数据分析平台/dist')
const outDir = path.resolve(process.argv[3] || repoRoot)

const assetsDir = path.join(refDist, 'assets')
const jsFile = fs.readdirSync(assetsDir).find((f) => f.endsWith('.js'))
const cssFile = fs.readdirSync(assetsDir).find((f) => f.endsWith('.css'))
if (!jsFile || !cssFile) throw new Error(`构建产物不完整: ${assetsDir}`)

const js = fs.readFileSync(path.join(assetsDir, jsFile), 'utf8')
const css = fs.readFileSync(path.join(assetsDir, cssFile), 'utf8')
const html = fs.readFileSync(path.join(refDist, 'index.html'), 'utf8')

// Vite 单入口产物已内联所有模块（无 import / export / import.meta），可当普通脚本内联。
if (/\bimport\s*\(/.test(js) || /\bexport\s*[{*]/.test(js) || js.includes('import.meta')) {
  throw new Error('构建产物含动态 import/export/import.meta，不能直接内联，请先调整构建配置')
}
// 避免内联脚本被 HTML 解析器提前闭合
const safeJs = js.replace(/<\/script/gi, '<\\/script')
const safeCss = css.replace(/<\/style/gi, '<\\/style')

