const { PNG } = require('D:/repository/门户/node_modules/pngjs')
const OUT = 'C:/Users/Administrator/AppData/Local/Temp/mm-align'
const IMPL = 'http://127.0.0.1:8092/market-monitor.html'
const REF = 'http://localhost:3000/'

async function capture(browser, url, name) {
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
  const resp = await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.evaluate(() => document.fonts.ready).catch(() => {})
  await page.waitForTimeout(3000)
  const file = path.join(OUT, name + '.png')
  await page.screenshot({ path: file, animations: 'disabled' })
  const info = await page.evaluate(() => ({
    title: document.title,
    bodyText: (document.body.innerText || '').slice(0, 160).replace(/\n/g, ' | '),
    rootChildren: document.getElementById('root')?.children.length,
    scrollH: document.documentElement.scrollHeight,
    canvasCount: document.querySelectorAll('canvas').length,
    svgCount: document.querySelectorAll('svg').length,
  }))
  console.log(name, 'status', resp && resp.status(), JSON.stringify({ errors: errors.slice(0, 6), info }))
  await page.close()
  return file
}
async function similarity(a, b, label) {
  const { default: pixelmatch } = await import(require('url').pathToFileURL('D:/repository/门户/node_modules/pixelmatch/index.js').href)
  const A = PNG.sync.read(fs.readFileSync(a)), B = PNG.sync.read(fs.readFileSync(b))
  const w = Math.min(A.width, B.width), h = Math.min(A.height, B.height)
  const crop = p => { const t = new PNG({ width: w, height: h }); PNG.bitblt(p, t, 0, 0, w, h, 0, 0); return t }
  const diff = new PNG({ width: w, height: h })
  const n = pixelmatch(crop(A).data, crop(B).data, diff.data, w, h, { threshold: 0.1, includeAA: false })
  fs.writeFileSync(path.join(OUT, label + '-diff.png'), PNG.sync.write(diff))
  console.log(`SIMILARITY ${label}: ${(100 * (1 - n / (w * h))).toFixed(3)}%`)
  return 100 * (1 - n / (w * h))
}
;(async () => {
  const browser = await chromium.launch({ headless: true })
  const ref = await capture(browser, REF, 'ref2')
  const impl = await capture(browser, IMPL, 'impl2')
  const fileImpl = await capture(browser, 'file:///D:/repository/门户/market-monitor.standalone.html', 'file2')
  await browser.close()
  await similarity(ref, impl, 'ref-vs-deployed')
  await similarity(ref, fileImpl, 'ref-vs-file')
})().catch(e => { console.error('FATAL', e); process.exit(1) })

