async function inspect(browser, url, name, blockFonts) {
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  if (blockFonts) {
    await page.route('**/fonts.googleapis.com/**', r => r.fulfill({ status: 200, contentType: 'text/css', body: '' }))
    await page.route('**/fonts.gstatic.com/**', r => r.abort())
  }
  const fontReqs = []
  page.on('request', r => { if (/fonts\.(googleapis|gstatic)/.test(r.url())) fontReqs.push(r.url().slice(0, 90)) })
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.evaluate(() => document.fonts.ready).catch(() => {})
  await page.waitForTimeout(3000)
  const fonts = await page.evaluate(() => ({
    checkNoto: document.fonts.check('16px "Noto Sans SC"'),
    checkJet: document.fonts.check('16px "JetBrains Mono"'),
    faces: [...document.fonts].slice(0, 6).map(f => `${f.family}|${f.status}`),
    count: document.fonts.size,
    sampleFamily: getComputedStyle(document.querySelector('h1, [class*="font-"]') || document.body).fontFamily,
  }))
  const file = path.join(OUT, name + '.png')
  await page.screenshot({ path: file, animations: 'disabled' })
  console.log(name, JSON.stringify({ fonts, fontReqs: fontReqs.length, fontReqsSample: fontReqs.slice(0, 3) }))
  await page.close()
  return file
}
