  const diff = new PNG({ width: w, height: h })
  const n = pixelmatch(crop(A).data, crop(B).data, diff.data, w, h, { threshold: 0.1, includeAA: false })
  fs.writeFileSync(path.join(OUT, label + '-diff.png'), PNG.sync.write(diff))
  console.log(`SIMILARITY ${label}: ${(100 * (1 - n / (w * h))).toFixed(3)}%`)
}
;(async () => {
  const browser = await chromium.launch({ headless: true })
