/**
 * 市场监测大屏「最新版本对齐」E2E 相似度测试
 *
 * 参考站（最新版本源码）: http://localhost:3000/
 * 对齐实现（nginx 部署站点）: http://127.0.0.1:8092/market-monitor.html
 * 离线单文件: market-monitor.standalone.html
 *
 * 运行:
 *   node tests/e2e/market-monitor-similarity.cjs
 * 可选环境变量:
 *   MM_REF_URL / MM_IMPL_URL / MM_STANDALONE / MM_NODE_MODULES / MM_THRESHOLD
 *
 * 判定: pixelmatch 逐像素相似度 >= 98%（默认），且交互后仍 >= 98%，无页面报错。
 * 说明: 两端均为 Chromium 渲染的同一份 React 构建产物；外部 Google Fonts 会
 *       导致 canvas 文字字体加载时序差异，故同时跑「字体桩化（确定性）」与
 *       「真实联网」两组，两组均须通过门禁。
 */
const fs = require('fs')
const path = require('path')
const assert = require('assert')
const { pathToFileURL } = require('url')

const REF_URL = process.env.MM_REF_URL || 'http://localhost:3000/'
const IMPL_URL = process.env.MM_IMPL_URL || 'http://127.0.0.1:8092/market-monitor.html'
const STANDALONE = process.env.MM_STANDALONE || path.resolve(__dirname, '../../market-monitor.standalone.html')
const THRESHOLD = Number(process.env.MM_THRESHOLD || 98)
const OUT = process.env.MM_OUT || path.resolve(__dirname, '../../test-results/mm-similarity')
fs.mkdirSync(OUT, { recursive: true })

// 依赖解析：优先本仓库 node_modules，其次主工作区 node_modules（worktree 场景）
function dep(name) {
  const candidates = [
    name,
    path.resolve(__dirname, '../../node_modules', name),
    path.join(process.env.MM_NODE_MODULES || '', name),
    'D:/repository/门户/node_modules/' + name,
  ]
  for (const c of candidates) {
    if (!c) continue
    try { return require(c) } catch (e) { /* try next */ }
  }
  throw new Error(`找不到依赖 ${name}，请设置 MM_NODE_MODULES`)
}
const { chromium } = dep('playwright')
const { PNG } = dep('pngjs')

let pixelmatch
async function getPixelmatch() {
  if (!pixelmatch) {
    for (const c of [
      path.resolve(__dirname, '../../node_modules/pixelmatch/index.js'),
      path.join(process.env.MM_NODE_MODULES || '', 'pixelmatch/index.js'),
      'D:/repository/门户/node_modules/pixelmatch/index.js',
    ]) {
      if (c && fs.existsSync(c)) { pixelmatch = (await import(pathToFileURL(c).href)).default; break }
    }
  }
  if (!pixelmatch) pixelmatch = (await import('pixelmatch')).default
  return pixelmatch
}

function stubExternalFonts(page) {
  return Promise.all([
    page.route('**/fonts.googleapis.com/**', r => r.fulfill({ status: 200, contentType: 'text/css', body: '' })),
    page.route('**/fonts.gstatic.com/**', r => r.abort()),
  ])
}

async function openPage(browser, url, { fonts = 'real', width = 1920, height = 1080 } = {}) {
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
  if (fonts === 'stub') await stubExternalFonts(page)
  const resp = await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.evaluate(() => document.fonts.ready).catch(() => {})
  await page.waitForTimeout(2600) // 等待 ECharts / motion 动画收敛
  return { page, errors, status: resp && resp.status() }
}

async function shot(page, name) {
  const file = path.join(OUT, name + '.png')
  await page.screenshot({ path: file, animations: 'disabled' })
  return file
}

async function similarity(a, b, label) {
  const pm = await getPixelmatch()
  const A = PNG.sync.read(fs.readFileSync(a))
  const B = PNG.sync.read(fs.readFileSync(b))
  const w = Math.min(A.width, B.width)
  const h = Math.min(A.height, B.height)
  const crop = p => { const t = new PNG({ width: w, height: h }); PNG.bitblt(p, t, 0, 0, w, h, 0, 0); return t }
  const diff = new PNG({ width: w, height: h })
  const count = pm(crop(A).data, crop(B).data, diff.data, w, h, { threshold: 0.1, includeAA: false })
  fs.writeFileSync(path.join(OUT, label + '-diff.png'), PNG.sync.write(diff))
  const pct = 100 * (1 - count / (w * h))
  console.log(`  ${label}: ${pct.toFixed(3)}%  (${w}x${h}, 差异像素 ${count})`)
  return pct
}

async function assertStructure(page, label) {
  const texts = ['苏州市房地产市场数据分析平台', '商品房上市量', '存量住房', '成交面积段结构', '商品房累计可售房屋', '未售房源', '购房人画像总览']
  for (const t of texts) {
    const visible = await page.getByText(t, { exact: false }).first().isVisible().catch(() => false)
    assert(visible, `${label}: 缺少关键文案「${t}」`)
  }
  const canvas = await page.locator('canvas').count()
  assert(canvas >= 6, `${label}: ECharts canvas 数量不足 (${canvas})`)
}

const results = []
function record(name, pct, errors) {
  results.push({ name, pct: Number(pct.toFixed(3)), errors })
  assert(pct >= THRESHOLD, `${name} 相似度 ${pct.toFixed(3)}% < ${THRESHOLD}%`)
  assert(errors.length === 0, `${name} 存在页面报错: ${errors.join(' | ')}`)
}

;(async () => {
  const browser = await chromium.launch({ headless: true })
  try {
    // 1) 确定性对比：外部字体桩化，消除 canvas 字体加载时序差异
    console.log('[1/4] 确定性对比（外部字体桩化）')
    {
      const r = await openPage(browser, REF_URL, { fonts: 'stub' })
      const i = await openPage(browser, IMPL_URL, { fonts: 'stub' })
      const a = await shot(r.page, 'ref-stub'), b = await shot(i.page, 'impl-stub')
      await assertStructure(i.page, '对齐实现')
      record('确定性-部署站点', await similarity(a, b, 'deterministic'), [...r.errors, ...i.errors])
      await r.page.close(); await i.page.close()
    }

    // 2) 真实联网对比（会加载 Google Fonts）
    console.log('[2/4] 真实联网对比')
    {
      const r = await openPage(browser, REF_URL)
      const i = await openPage(browser, IMPL_URL)
      const a = await shot(r.page, 'ref-real'), b = await shot(i.page, 'impl-real')
      record('真实联网-部署站点', await similarity(a, b, 'real-network'), [...r.errors, ...i.errors])
      await r.page.close(); await i.page.close()
    }

    // 3) 离线单文件对比（file:// 直开）
    console.log('[3/4] 离线单文件对比')
    if (fs.existsSync(STANDALONE)) {
      const r = await openPage(browser, REF_URL, { fonts: 'stub' })
      const i = await openPage(browser, pathToFileURL(STANDALONE).href, { fonts: 'stub' })
      const a = await shot(r.page, 'ref-file'), b = await shot(i.page, 'impl-file')
      await assertStructure(i.page, '离线单文件')
      record('离线单文件', await similarity(a, b, 'standalone'), [...r.errors, ...i.errors])
      await r.page.close(); await i.page.close()
    } else {
      console.log('  跳过（未找到单文件）')
    }

    // 4) 交互对齐：监测范围切「姑苏区」后仍须像素级一致
    console.log('[4/4] 交互对齐（监测范围 = 姑苏区）')
    {
      const r = await openPage(browser, REF_URL, { fonts: 'stub' })
      const i = await openPage(browser, IMPL_URL, { fonts: 'stub' })
      for (const [p, label] of [[r.page, '参考'], [i.page, '实现']]) {
        await p.locator('select[aria-label="监测范围选择"]').selectOption({ label: '姑苏区' })
        await p.waitForTimeout(1200)
        assert(await p.getByText('姑苏区', { exact: false }).first().isVisible().catch(() => false), `${label}: 筛选后未出现姑苏区`)
      }
      const a = await shot(r.page, 'ref-district'), b = await shot(i.page, 'impl-district')
      record('交互-姑苏区筛选', await similarity(a, b, 'district'), [...r.errors, ...i.errors])
      await r.page.close(); await i.page.close()
    }

    console.log('\n=== E2E 相似度报告 ===')
    for (const x of results) console.log(`  ${x.name}: ${x.pct}%  ${x.pct >= THRESHOLD ? 'PASS' : 'FAIL'}`)
    console.log(`门禁: >= ${THRESHOLD}%  ->  ALL PASS (${results.length}/${results.length})`)
    fs.writeFileSync(path.join(OUT, 'report.json'), JSON.stringify({ threshold: THRESHOLD, results }, null, 2))
  } finally {
    await browser.close()
  }
})().catch(e => { console.error('\nE2E FAILED:', e.message); process.exit(1) })

