// 4) 交互对齐：监测范围切「姑苏区」后仍须像素级一致
console.log('[4/4] 交互对齐（监测范围 = 姑苏区）')
{
  const r = await openPage(browser, REF_URL, { fonts: 'stub' })
  const i = await openPage(browser, IMPL_URL, { fonts: 'stub' })
  const before = []
  for (const [p, label] of [[r.page, '参考'], [i.page, '实现']]) {
    before.push(await shot(p, `${label === '参考' ? 'ref' : 'impl'}-district-before`))
    await p.locator('select[aria-label="监测范围选择"]').selectOption({ label: '姑苏区' })
    await p.waitForTimeout(1200)
    const value = await p.locator('select[aria-label="监测范围选择"]').inputValue()
    assert.strictEqual(value, '姑苏', `${label}: 监测范围下拉未生效 (value=${value})`)
    const banner = await p.getByRole('heading', { name: '姑苏区' }).isVisible().catch(() => false)
    assert(banner, `${label}: 筛选后未出现姑苏区情报横幅`)
  }
  // 交互确实改变了画面（而非静态截图）
  for (const [idx, label] of [[0, '参考'], [1, '实现']]) {
    const after = await shot(idx === 0 ? r.page : i.page, `${idx === 0 ? 'ref' : 'impl'}-district`)
    const changed = await similarity(before[idx], after, `interaction-changed-${idx}`)
    assert(changed < 99.5, `${label}: 切换监测范围后画面未变化（疑似交互失效）`)
    if (idx === 0) global.__refDistrictAfter = after
    else global.__implDistrictAfter = after
  }
  record('交互-姑苏区筛选', await similarity(global.__refDistrictAfter, global.__implDistrictAfter, 'district'), [...r.errors, ...i.errors])
  await r.page.close(); await i.page.close()
}

