/**
 * 让门户站点的大屏路由 #/market-monitor 指向「最新版本」对齐后的大屏页面。
 *
 * 背景：门户 SPA 的 /market-monitor 是旧版 Vue2 移植；对齐全新版本后，
 * 单文件产物 dist/market-monitor.html 与参考站 100% 一致。此脚本在构建产物
 * dist/index.html 的 <head> 内注入一段幂等的 hash 路由跳转，使直接访问
 * /index.html#/market-monitor 或 SPA 内跳转到该 hash 时都切到对齐页面。
 *
 * 用法（每次 npm run build 之后执行）：
 *   node scripts/apply-market-monitor-route.mjs [dist目录]
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const repoRoot = path.resolve(__dirname, '..')
const distDir = path.resolve(process.argv[2] || path.join(repoRoot, 'dist'))
const indexFile = path.join(distDir, 'index.html')
const MARKER = 'id="mm-route-align"'

const snippet = `<script ${MARKER}>(function(){
  var target='/market-monitor.html';
  function align(){ if(location.hash.indexOf('#/market-monitor')===0 && location.pathname.indexOf('market-monitor.html')<0){ location.replace(target); } }
  align();
  window.addEventListener('hashchange', align);
})()</script>`

if (!fs.existsSync(indexFile)) throw new Error(`找不到构建产物: ${indexFile}`)
let html = fs.readFileSync(indexFile, 'utf8')
if (html.includes(MARKER)) {
  console.log('already patched:', indexFile)
} else {
  const at = html.indexOf('<head>')
  if (at < 0) throw new Error('dist/index.html 缺少 <head> 标签')
  html = html.slice(0, at + 6) + '\n' + snippet + html.slice(at + 6)
  fs.writeFileSync(indexFile, html, 'utf8')
  console.log('patched:', indexFile)
}

