const fs = require('fs')
const path = require('path')
const { chromium } = require('D:/repository/门户/node_modules/playwright')
const { PNG } = require('D:/repository/门户/node_modules/pngjs')
const OUT = 'C:/Users/Administrator/AppData/Local/Temp/mm-align'
const REF = 'http://localhost:3000/'
const IMPL = 'http://127.0.0.1:8092/market-monitor.html'

async function cap(browser, url, w, h, name) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 })
  await page.route('**/fonts.googleapis.com/**', r => r.fulfill({ status: 200, contentType: 'text/css', body: '' }))
  await page.route('**/fonts.gstatic.com/**', r => r.abort())
  const errs = []
  page.on('pageerror', e => errs.push(e.message))
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.evaluate(() => document.fonts.ready).catch(() => {})
  await page.waitForTimeout(2600)
  const f = path.join(OUT, name + '.png')
  await page.screenshot({ path: f, animations: 'disabled' })
  const info = await page.evaluate(() => ({ title: document.title, text: (document.body.innerText || '').slice(0, 60), scrollH: document.documentElement.scrollHeight }))
  await page.close()
  return { f, errs, info }
}
async function sim(a, b, label) {
  const { default: pixelmatch } = await import(require('url').pathToFileURL('D:/repository/门户/node_modules/pixelmatch/index.js').href)
  const A = PNG.sync.read(fs.readFileSync(a)), B = PNG.sync.read(fs.readFileSync(b))
  const w = Math.min(A.width, B.width), h = Math.min(A.height, B.height)
  const crop = p => { const t = new PNG({ width: w, height: h }); PNG.bitblt(p, t, 0, 0, w, h, 0, 0); return t }
  const d = new PNG({ width: w, height: h })
  const n = pixelmatch(crop(A).data, crop(B).data, d.data, w, h, { threshold: 0.1, includeAA: false })
  console.log(`${label}: ${(100 * (1 - n / (w * h))).toFixed(3)}% (${w}x${h})`)
}
;(async () => {
  const browser = await chromium.launch({ headless: true })
  for (const [w, h] of [[1920, 1040], [1366, 768], [1600, 900]]) {
    const r = await cap(browser, REF, w, h, `vp-${w}-ref`)
    const i = await cap(browser, IMPL, w, h, `vp-${w}-impl`)
    console.log(`viewport ${w}x${h}`, 'errors', r.errs.length + i.errs.length, 'scrollH', r.info.scrollH, i.info.scrollH)
    await sim(r.f, i.f, `vp-${w}x${h}`)
  }
  // 门户入口未被补丁破坏（非大屏 hash 不跳转，Vue SPA 正常挂载）
  const p = await browser.newPage({ viewport: { width: 1366, height: 768 } })
  const errs = []
  p.on('pageerror', e => errs.push(e.message))
  await p.goto('http://127.0.0.1:8092/index.html#/UnifiedLogin', { waitUntil: 'domcontentloaded', timeout: 60000 })
  await p.waitForTimeout(3000)
  const state = await p.evaluate(() => ({ url: location.href, appChildren: document.getElementById('app')?.children.length, text: (document.body.innerText || '').slice(0, 80) }))
  console.log('portal-entry', JSON.stringify({ errs: errs.slice(0, 3), state }))
  await p.close()
  await browser.close()
})().catch(e => { console.error('FATAL', e); process.exit(1) })
